package com.centurywar.engine

import java.util.Locale

/**
 * Teksty gry. Gra rysuje wszystko na Canvas, więc trzymamy teksty w kodzie zamiast
 * w zasobach XML. Każdy wpis to tablica w kolejności [CODES]; brakujący lub pusty
 * przekład zastępuje angielski. Formy oddziela | (pl/uk: 1, 2–4, pozostałe;
 * pozostałe języki: pojedyncza, mnoga; tr: jedna forma). Nowy język wymaga kolumny.
 */
object L {
    /** Kody języków (ISO 639-1) w kolejności kolumn tabeli. */
    val CODES = arrayOf("pl", "en", "de", "es", "fr", "it", "pt", "uk", "nl", "tr")
    /** Nazwy języków w nich samych (przycisk w Ustawieniach). */
    val NAMES = arrayOf("Polski", "English", "Deutsch", "Español", "Français", "Italiano", "Português", "Українська", "Nederlands", "Türkçe")
    const val PL = 0
    const val EN = 1

    /** Indeks bieżącego języka w [CODES]. */
    var lang: Int = systemLang()

    /** Zgodność wsteczna: true = polski. */
    var polish: Boolean
        get() = lang == PL
        set(v) { lang = if (v) PL else EN }

    /** Indeks języka dla kodu (np. "de", "pt-BR", "pt_BR") albo -1. */
    fun indexOf(code: String): Int =
        CODES.indexOf(code.substringBefore('-').substringBefore('_').lowercase(Locale.ROOT))

    /** Język systemu, jeśli go obsługujemy; inaczej angielski. */
    fun systemLang(): Int {
        val idx = indexOf(Locale.getDefault().language)
        return if (idx >= 0) idx else EN
    }

    /** Ustawia język z kodu profilu ("" = systemowy). */
    fun setCode(code: String) {
        val idx = if (code.isEmpty()) -1 else indexOf(code)
        lang = if (idx >= 0) idx else systemLang()
    }

    operator fun get(key: String): String = text(key, lang)

    /** Tekst w danym języku (brak lub pusty przekład → angielski). */
    fun text(key: String, langIdx: Int): String {
        val e = table[key] ?: return key
        val s = e.getOrNull(langIdx)
        val value = if (s.isNullOrEmpty()) e[EN] else s
        // Zwykłe pobranie nie ujawnia separatora form.
        return value.substringAfterLast('|')
    }

    fun f(key: String, vararg args: Any): String = String.format(Locale.ROOT, get(key), *args)

    /** Jak [f], ale w języku [langIdx] (powiadomienia: bez zmiany języka gry). */
    fun fIn(langIdx: Int, key: String, vararg args: Any): String =
        String.format(Locale.ROOT, text(key, langIdx), *args)

    /** Indeks formy liczebnika w kolejności języków CODES. */
    fun pluralIndex(langIdx: Int, n: Long): Int {
        val last = Math.floorMod(n, 10L)
        val lastTwo = Math.floorMod(n, 100L)
        return when (langIdx) {
            PL -> when {
                n == 1L -> 0
                last in 2L..4L && lastTwo !in 12L..14L -> 1
                else -> 2
            }
            7 -> when { // uk
                last == 1L && lastTwo != 11L -> 0
                last in 2L..4L && lastTwo !in 12L..14L -> 1
                else -> 2
            }
            4 -> if (n == 0L || n == 1L) 0 else 1 // fr
            9 -> 0 // tr
            else -> if (n == 1L) 0 else 1
        }
    }

    /** n wybiera formę; args ustalają kolejność argumentów (np. %s przed %d). */
    fun plural(key: String, n: Long, vararg args: Any): String = pluralIn(lang, key, n, *args)

    /** Jak [plural], ale w języku [langIdx]. */
    fun pluralIn(langIdx: Int, key: String, n: Long, vararg args: Any): String {
        val e = table[key]
        val raw = e?.getOrNull(langIdx)?.takeIf { it.isNotEmpty() }
            ?: e?.getOrNull(EN) ?: key
        val forms = raw.split('|')
        val form = forms[pluralIndex(langIdx, n).coerceAtMost(forms.lastIndex)]
        return if (args.isEmpty()) String.format(Locale.ROOT, form, n)
            else String.format(Locale.ROOT, form, *args)
    }

    /** Krótki komunikat startowy bez inicjalizowania całej tabeli tłumaczeń. */
    fun startupText(): String = when (lang) {
        0 -> "Ładowanie…"
        1 -> "Loading…"
        2 -> "Wird geladen…"
        3 -> "Cargando…"
        4 -> "Chargement…"
        5 -> "Caricamento…"
        6 -> "Carregando…"
        7 -> "Завантаження…"
        8 -> "Laden…"
        else -> "Yükleniyor…"
    }

    /** Klucze tabeli (dla testów). */
    val keys: Set<String> get() = table.keys

    /** Surowy wpis tabeli (dla testów). */
    fun raw(key: String): Array<out String>? = table[key]

